"""Company profiles for the mock source systems: generated by Claude, stored, then served consistently.

Generation reuses the validated structured-output generator (app/ingestion/ai_generator.py), so a profile
only reaches the database if it passed the same checks as production data (no impossible counts).
"""
from __future__ import annotations

import re
import threading
from concurrent.futures import ThreadPoolExecutor
from dataclasses import dataclass, field
from typing import Any

from sqlalchemy import func, select
from sqlalchemy.orm import Session, sessionmaker

from app.core.config import settings
from app.db.models import Company, MockCompanyData
from app.ingestion.ai_generator import generate_batch
from app.ingestion.stubgen import CompanyRaw, assign_archetype, synthetic_company

BATCH = 8
WORKERS = 4
_CODE = re.compile(r"^IC(\d+)$")
_locks: dict[str, threading.Lock] = {}
_locks_guard = threading.Lock()


def model_name() -> str:
    return settings.mock_source_model or settings.stub_generator_model


def archetype_for(code: str, total: int) -> str:
    m = _CODE.match(code)
    return assign_archetype(int(m.group(1)) - 1 if m else sum(map(ord, code)), max(total, 1))


def known_company(db: Session, code: str) -> bool:
    return db.scalar(select(Company.id).where(Company.code == code, Company.active)) is not None


def get_profile(db: Session, code: str) -> MockCompanyData | None:
    return db.scalar(select(MockCompanyData).where(MockCompanyData.company_code == code))


def profiles(db: Session) -> dict[str, CompanyRaw]:
    return {r.company_code: CompanyRaw(**r.raw) for r in db.scalars(select(MockCompanyData))}


def _save(db: Session, code: str, raw: CompanyRaw, origin: str) -> None:
    db.add(MockCompanyData(company_code=code, archetype=raw.archetype, origin=origin,
                           model=model_name() if origin == "ai" else None, raw=raw.model_dump()))
    db.commit()


class GenerationUnavailable(RuntimeError):
    """The AI call failed and fallback data is not allowed."""


def ensure_one(db: Session, client: Any | None, code: str) -> MockCompanyData:
    """Make sure one company has a profile, generating it on first need. One generation per company at a time."""
    existing = get_profile(db, code)
    if existing:
        return existing
    with _locks_guard:
        lock = _locks.setdefault(code, threading.Lock())
    with lock:
        db.expire_all()
        existing = get_profile(db, code)
        if existing:
            return existing
        total = db.scalar(select(func.count(Company.id))) or 1
        arch = archetype_for(code, total)
        good: dict[str, CompanyRaw] = {}
        if client is not None:
            good, _err = generate_batch(client, model_name(), [(code, arch)])
        if code in good:
            _save(db, code, good[code], "ai")
        elif settings.mock_sources_allow_fallback:
            _save(db, code, synthetic_company(code, arch), "fallback")  # type: ignore[arg-type]
        else:
            raise GenerationUnavailable("the data generator is unavailable")
        return get_profile(db, code)  # type: ignore[return-value]


@dataclass
class GenResult:
    ai: int = 0
    fallback: int = 0
    failed: list[str] = field(default_factory=list)
    notes: list[str] = field(default_factory=list)


def generate_missing(factory: sessionmaker, client: Any, on_progress=None) -> GenResult:
    """Generate every company that has no profile yet: batches of 8, four at a time, then one retry round."""
    res = GenResult()
    with factory() as db:
        all_codes = list(db.scalars(select(Company.code).where(Company.active).order_by(Company.code)))
        have = set(db.scalars(select(MockCompanyData.company_code)))
    todo = [c for c in all_codes if c not in have]
    total = len(all_codes)
    assign = {c: archetype_for(c, total) for c in todo}

    def run_batches(codes: list[str]) -> list[str]:
        batches = [[(c, assign[c]) for c in codes[i:i + BATCH]] for i in range(0, len(codes), BATCH)]
        left: list[str] = []
        with ThreadPoolExecutor(WORKERS) as pool:
            for batch, (good, err) in zip(batches, pool.map(lambda b: generate_batch(client, model_name(), b), batches),
                                          strict=True):
                if err:
                    res.notes.append(f"{batch[0][0]}..: {err}")
                with factory() as db:
                    for code, _ in batch:
                        if code in good:
                            _save(db, code, good[code], "ai")
                            res.ai += 1
                        else:
                            left.append(code)
                if on_progress:
                    on_progress(res.ai + res.fallback)
        return left

    left = run_batches(todo)
    if left:  # one retry round for anything the model got wrong or dropped
        left = run_batches(left)
    for code in left:
        if settings.mock_sources_allow_fallback:
            with factory() as db:
                _save(db, code, synthetic_company(code, assign[code]), "fallback")  # type: ignore[arg-type]
            res.fallback += 1
        else:
            res.failed.append(code)
    return res


def status(db: Session) -> dict:
    rows = db.execute(select(MockCompanyData.origin, func.count()).group_by(MockCompanyData.origin)).all()
    by = {o: n for o, n in rows}
    total = db.scalar(select(func.count(Company.id)).where(Company.active)) or 0
    return {"companies": total, "generated": sum(by.values()), "ai": by.get("ai", 0), "fallback": by.get("fallback", 0),
            "model": model_name()}
